head.script:
// =============================================================================
/**
 * stf 업무 모듈에서 추출한 업무공통(KRX 고유) 함수.
 * 데이터셋 복사 / 콤보 데이터셋 / 그리드 헤더·패널 메시지 / 기간·일자 UI /
 * 업무번호 생성 / 공시뷰어 / 로그저장 / 연결주석 사유.
 * 함수명은 camelCase 로 표준화하고, 각 JSDoc 에 AS-IS 원본명(origin: stf.xml)을 병기한다.
 * 인쇄/리포트(report.xml, *_print.xml) 함수는 본 파일에 두지 않고 print.xml($c.print)로 분리한다.
 *
 * 단순 문자열/숫자/날짜/검증/팝업/세션 함수는 기존 $c.* 공통함수로 매핑(이관)되었으며 본 파일에 포함하지 않는다.
 * 매핑 내역은 src/as-is/stf/md/gcc_mapping_and_biz_common.md 참조.
 *
 * @author Inswave Systems
 * @class stf
 * @namespace $c.stf
 */
// =============================================================================

scwin.onpageload = function () {

};

// 화면처리구분코드 (Action 클래스를 거치지 않는 엑셀다운로드 등 로그 기록 시 사용)
scwin.SCREN_PROCS_TP_CD_01 = "01"; // 조회
scwin.SCREN_PROCS_TP_CD_02 = "02"; // 입력
scwin.SCREN_PROCS_TP_CD_03 = "03"; // 수정
scwin.SCREN_PROCS_TP_CD_04 = "04"; // 삭제
scwin.SCREN_PROCS_TP_CD_05 = "05"; // 인쇄
scwin.SCREN_PROCS_TP_CD_06 = "06"; // 화면출력
scwin.SCREN_PROCS_TP_CD_07 = "07"; // 엑셀저장
scwin.SCREN_PROCS_TP_CD_08 = "08"; // PC저장

// -----------------------------------------------------------------------------
// 1. 데이터셋/그리드 보조 (origin: stf.xml)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name copyDataSet
 * @description 데이터셋 오브젝트 간에 데이터를 복사한다. 복사대상 데이터셋의 기존 데이터는 모두 삭제된다.
 * features 의 copyHeader=yes 면 컬럼 헤더까지 복사한다.
 * (AS-IS: CopyDataSet, origin: stf.xml)
 * @param {Object} oOriginDataSet 원본 DataSet
 * @param {Object} oTargetDataSet 복사 대상 DataSet
 * @param {String} features 옵션 문자열 (copyHeader/resetStatus/rowFrom/rowCnt). 예: "copyHeader=yes,rowFrom=1,rowCnt=2"
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.copyDataSet(oOrigin, oTarget, "copyHeader=no");
 */
scwin.copyDataSet = function (oOriginDataSet, oTargetDataSet, features) {
    var featureNames = ["copyHeader", "resetStatus", "rowFrom", "rowCnt"];
    var featureValues = [true, true, 1, oOriginDataSet.getTotalRow()];
    var featureTypes = ["boolean", "boolean", "number", "number"];
    if (features != null) {
        scwin.__cfParseFeature(features, featureNames, featureValues, featureTypes);
    }
    var copyHeader = featureValues[0];
    var resetStatus = featureValues[1];
    var rowFrom = featureValues[2];
    var rowCnt = featureValues[3];
    if (copyHeader == true) {
        scwin.copyDataSetHeader(oOriginDataSet, oTargetDataSet);
    }
    oTargetDataSet.ClearData();
    if (oOriginDataSet.getTotalRow() > 0) {
        var temp = oTargetDataSet.dataid; // ImportData 후 기존 dataid 속성이 지워지는 것을 방지.
        oTargetDataSet.ImportData(oOriginDataSet.ExportData(rowFrom, rowCnt, true));
        oTargetDataSet.dataid = temp;
        if (resetStatus == true) {
            oTargetDataSet.ResetStatus();
        }
    }
};

/**
 * @method
 * @name copyDataSetHeader
 * @description 데이터셋 오브젝트 간에 컬럼 헤더(컬럼ID/타입/사이즈/속성) 정보를 복사한다.
 * (AS-IS: CopyDataSetHeader, origin: stf.xml)
 * @param {Object} oOriginDataSet 원본 DataSet
 * @param {Object} oTargetDataSet 복사 대상 DataSet
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.copyDataSetHeader(oOrigin, oTarget);
 */
scwin.copyDataSetHeader = function (oOriginDataSet, oTargetDataSet) {
    var DsHeader = "";
    var colId = "";
    var colType = "";
    var colProp = "";
    var colSize = "";
    var colDec = "";
    var colIndex = "";
    scwin.__copyDataSetHeaderDummy(oTargetDataSet);
    for (var i = 1; i <= oOriginDataSet.getTotalCol(); i++) {
        colId = oOriginDataSet.ColumnID(i);
        colIndex = oOriginDataSet.ColumnIndex(colId);
        colSize = oOriginDataSet.ColumnSize(colIndex);
        colDec = oOriginDataSet.ColumnDec(colIndex);
        switch (oOriginDataSet.ColumnType(colIndex)) {
            case 1: colType = "String"; break;
            case 2: colType = "Integer"; break;
            case 3: colType = "Decimal"; break;
            case 4: colType = "Date"; break;
            case 5: colType = "URL"; break;
            case 9: colType = "BIGINT"; break;
            default: colType = ""; break;
        }
        switch (oOriginDataSet.ColumnProp(i)) {
            case 0: colProp = "NORMAL"; break;
            case 1: colProp = "CONSTANT"; break;
            case 2: colProp = "KEYVALUE"; break;
            default: colProp = ""; break;
        }
        if (colType == "Decimal") {
            DsHeader = DsHeader + colId + ":" + colType + "(" + colSize + "." + colDec + "):" + colProp + ",";
        } else {
            DsHeader = DsHeader + colId + ":" + colType + "(" + colSize + "):" + colProp + ",";
        }
    }
    DsHeader = DsHeader.substr(0, DsHeader.length - 1);
    oTargetDataSet.SetDataHeader(DsHeader);
};

/**
 * @method
 * @name copyDataSetForTemp
 * @description 매매거래정지 임시보관함 전송 시 사용하는 데이터셋 복사. copyDataSet 과 동일하되
 * 헤더 복사를 copyDataSetHeaderForTemp(특정 컬럼 사이즈 보정)로 처리한다.
 * (AS-IS: CopyDataSetForTemp, origin: stf.xml)
 * @param {Object} oOriginDataSet 원본 DataSet
 * @param {Object} oTargetDataSet 복사 대상 DataSet
 * @param {String} features 옵션 문자열 (copyHeader/resetStatus/rowFrom/rowCnt)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.copyDataSetForTemp(oOrigin, oTarget, "copyHeader=yes");
 */
scwin.copyDataSetForTemp = function (oOriginDataSet, oTargetDataSet, features) {
    var featureNames = ["copyHeader", "resetStatus", "rowFrom", "rowCnt"];
    var featureValues = [true, true, 1, oOriginDataSet.getTotalRow()];
    var featureTypes = ["boolean", "boolean", "number", "number"];
    if (features != null) {
        scwin.__cfParseFeature(features, featureNames, featureValues, featureTypes);
    }
    var copyHeader = featureValues[0];
    var resetStatus = featureValues[1];
    var rowFrom = featureValues[2];
    var rowCnt = featureValues[3];
    if (copyHeader == true) {
        scwin.copyDataSetHeaderForTemp(oOriginDataSet, oTargetDataSet);
    }
    oTargetDataSet.ClearData();
    if (oOriginDataSet.getTotalRow() > 0) {
        var temp = oTargetDataSet.dataid;
        oTargetDataSet.ImportData(oOriginDataSet.ExportData(rowFrom, rowCnt, true));
        oTargetDataSet.dataid = temp;
        if (resetStatus == true) {
            oTargetDataSet.ResetStatus();
        }
    }
};

/**
 * @method
 * @name copyDataSetHeaderForTemp
 * @description 임시보관함용 데이터셋 헤더 복사. copyDataSetHeader 와 동일하되
 * TRD_HALT_TP_NM 컬럼 사이즈를 80 으로 보정한다.
 * (AS-IS: CopyDataSetHeaderForTemp, origin: stf.xml)
 * @param {Object} oOriginDataSet 원본 DataSet
 * @param {Object} oTargetDataSet 복사 대상 DataSet
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.copyDataSetHeaderForTemp(oOrigin, oTarget);
 */
scwin.copyDataSetHeaderForTemp = function (oOriginDataSet, oTargetDataSet) {
    var DsHeader = "";
    var colId = "";
    var colType = "";
    var colProp = "";
    var colSize = "";
    var colDec = "";
    var colIndex = "";
    scwin.__copyDataSetHeaderDummy(oTargetDataSet);
    for (var i = 1; i <= oOriginDataSet.getTotalCol(); i++) {
        colId = oOriginDataSet.ColumnID(i);
        colIndex = oOriginDataSet.ColumnIndex(colId);
        colSize = oOriginDataSet.ColumnSize(colIndex);
        colDec = oOriginDataSet.ColumnDec(colIndex);
        switch (oOriginDataSet.ColumnType(colIndex)) {
            case 1: colType = "String"; break;
            case 2: colType = "Integer"; break;
            case 3: colType = "Decimal"; break;
            case 4: colType = "Date"; break;
            case 5: colType = "URL"; break;
            case 9: colType = "BIGINT"; break;
            default: colType = ""; break;
        }
        switch (oOriginDataSet.ColumnProp(i)) {
            case 0: colProp = "NORMAL"; break;
            case 1: colProp = "CONSTANT"; break;
            case 2: colProp = "KEYVALUE"; break;
            default: colProp = ""; break;
        }
        if (colType == "Decimal") {
            DsHeader = DsHeader + colId + ":" + colType + "(" + colSize + "." + colDec + "):" + colProp + ",";
        } else {
            if (colId == "TRD_HALT_TP_NM") {
                colSize = 80;
            }
            DsHeader = DsHeader + colId + ":" + colType + "(" + colSize + "):" + colProp + ",";
        }
    }
    DsHeader = DsHeader.substr(0, DsHeader.length - 1);
    oTargetDataSet.SetDataHeader(DsHeader);
};

/**
 * @method
 * @name __copyDataSetHeaderDummy
 * @description (내부) 복사 대상 데이터셋을 더미 헤더 메시지로 초기화한다. copyDataSetHeader 보조.
 * (AS-IS: CopyDataSetHeaderDummy, origin: stf.xml)
 * @param {Object} oTargetDataSet 대상 DataSet
 * @returns {void}
 * @hidden Y
 * @exception
 * @example scwin.__copyDataSetHeaderDummy(oTarget);
 */
scwin.__copyDataSetHeaderDummy = function (oTargetDataSet) {
    var oldSyscLoad = oTargetDataSet.SyncLoad;
    oTargetDataSet.SyncLoad = true;
    oTargetDataSet.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DUMMY_INOUT";
    oTargetDataSet.reset();
    oTargetDataSet.SyncLoad = oldSyscLoad;
};

/**
 * @method
 * @name __cfParseFeature
 * @description (내부) feature 문자열("name=value,...")을 파싱하여 값/타입 배열에 셋팅한다. copyDataSet 계열 보조.
 * (AS-IS: cfParseFeature, origin: stf.xml)
 * @param {String} features feature 문자열
 * @param {Array} fNameArray 추출할 feature 이름 배열
 * @param {Array} fValueArray 기본값 배열(결과가 채워짐)
 * @param {Array} fTypeArray 데이터 타입 배열(string/number/boolean)
 * @returns {void}
 * @hidden Y
 * @exception
 * @example scwin.__cfParseFeature(features, names, values, types);
 */
scwin.__cfParseFeature = function (features, fNameArray, fValueArray, fTypeArray) {
    if (features == null) {
        return;
    }
    var featureArray = features.split(",");
    var featurePair;
    for (var i = 0; i < featureArray.length; i++) {
        featurePair = $c.str.trim(featureArray[i]).split("=");
        for (var j = 0; j < fNameArray.length; j++) {
            if (featurePair[0] == fNameArray[j]) {
                switch (fTypeArray[j]) {
                    case "string":
                        fValueArray[j] = featurePair[1];
                        break;
                    case "number":
                        fValueArray[j] = Number(featurePair[1]);
                        break;
                    case "boolean":
                        if (featurePair[1].toUpperCase() == "YES" || featurePair[1].toUpperCase() == "TRUE" || featurePair[1] == "1") {
                            fValueArray[j] = true;
                        } else {
                            fValueArray[j] = false;
                        }
                        break;
                }
            }
        }
    }
};

/**
 * @method
 * @name fillGridHeaderTotalCnt
 * @description 페이징 없이 전체 건수만 표시할 때 그리드 헤더 패널에 건수를 표시한다.
 * (AS-IS: FillGridHeaderTotalCnt, origin: stf.xml)
 * AS-IS 의 DOM innerHTML(HTML 테이블 문자열) 구성 → WebSquare 컴포넌트 API(setValue/show)로 교체.
 * @param {Number} vRsltCnt 표시할 건수
 * @param {Object} panelID 건수를 표시할 컴포넌트(setValue/show 보유)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.fillGridHeaderTotalCnt(totalCnt, grp_total);
 */
scwin.fillGridHeaderTotalCnt = function (vRsltCnt, panelID) {
    panelID.setValue(vRsltCnt);
    panelID.show("");
};

/**
 * @method
 * @name fillGridHeaderTotalCntEsg
 * @description 전체 건수 표시(ESG 변형 — 0 값도 표시). 컴포넌트 API(setValue/show) 사용.
 * (AS-IS: FillGridHeaderTotalCntESG, origin: stf.xml)
 * @param {Number} vRsltCnt 표시할 건수
 * @param {Object} panelID 건수를 표시할 컴포넌트(setValue/show 보유)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.fillGridHeaderTotalCntEsg(totalCnt, grp_total);
 */
scwin.fillGridHeaderTotalCntEsg = function (vRsltCnt, panelID) {
    panelID.setValue(vRsltCnt);
    panelID.show("");
};

// -----------------------------------------------------------------------------
// 2. 콤보 데이터셋 (origin: stf.xml)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name comboCbDataSet
 * @description 조회조건의 "페이지당 건수" 콤보 데이터(10/50/100/500/1000/전체)를 지정한다.
 * (AS-IS: Combo_CBDataSet, origin: stf.xml) — CBData 문자열 → itemArr 객체 배열로 교체.
 * @param {Object} sval 적용할 콤보 컴포넌트
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.comboCbDataSet(cmb_cnt);
 */
scwin.comboCbDataSet = function (sval) {
    sval.itemArr = [
        { label: "10", value: "10건", orgLabel: "10" },
        { label: "50", value: "50건", orgLabel: "50" },
        { label: "100", value: "100건", orgLabel: "100" },
        { label: "500", value: "500건", orgLabel: "500" },
        { label: "1000", value: "1000건", orgLabel: "1000" },
        { label: "0", value: "전체", orgLabel: "0" }
    ];
    sval.setSelectedIndex(1);
};

/**
 * @method
 * @name comboCbDataSetLimit
 * @description 조회조건의 "페이지당 건수" 콤보 데이터(최대 10,000건 제한 변형)를 지정한다.
 * (AS-IS: Combo_CBDataSetLimit, origin: stf.xml) — CBData 문자열 → itemArr 객체 배열로 교체.
 * @param {Object} sval 적용할 콤보 컴포넌트
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.comboCbDataSetLimit(cmb_cnt);
 */
scwin.comboCbDataSetLimit = function (sval) {
    sval.itemArr = [
        { label: "10", value: "10건", orgLabel: "10" },
        { label: "50", value: "50건", orgLabel: "50" },
        { label: "100", value: "100건", orgLabel: "100" },
        { label: "500", value: "500건", orgLabel: "500" },
        { label: "1000", value: "1,000건", orgLabel: "1000" },
        { label: "10000", value: "10,000건", orgLabel: "10000" }
    ];
    sval.setSelectedIndex(1);
};

/**
 * @method
 * @name comboCbDataSetPeriod
 * @description 조회조건의 "기간 선택" 콤보 데이터(1주일전~2년전)를 지정한다.
 * (AS-IS: Combo_CBDataSetPeriod, origin: stf.xml) — CBData 문자열 → itemArr 객체 배열로 교체.
 * @param {Object} sval 적용할 콤보 컴포넌트
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.comboCbDataSetPeriod(cmb_period);
 */
scwin.comboCbDataSetPeriod = function (sval) {
    sval.itemArr = [
        { label: "1주일전", value: 1, orgLabel: "1주일전" },
        { label: "1개월전", value: 2, orgLabel: "1개월전" },
        { label: "3개월전", value: 3, orgLabel: "3개월전" },
        { label: "6개월전", value: 4, orgLabel: "6개월전" },
        { label: "1년전", value: 5, orgLabel: "1년전" },
        { label: "2년전", value: 6, orgLabel: "2년전" }
    ];
};

/**
 * @method
 * @name getComboTextValue
 * @description 콤보 컴포넌트의 현재 선택 항목 TEXT(라벨) 값을 반환한다.
 * (AS-IS: fn_getComboTextValue, origin: stf.xml)
 * @param {Object} obj 콤보 컴포넌트
 * @returns {String} 선택 항목의 TEXT 값
 * @hidden N
 * @exception
 * @example var txt = $c.stf.getComboTextValue(cmb_dep);
 */
scwin.getComboTextValue = function (obj) {
    return obj.ValueOfIndex("TEXT", obj.getSelectedIndex());
};

// -----------------------------------------------------------------------------
// 3. UI/메시지 (origin: stf.xml)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name panelMsg
 * @description 지정 패널 영역에 메시지를 표시한다. 예) "시장조치일정 : 63 개 (미확정 40, 확정 23)"
 * (AS-IS: PanelMsg, origin: stf.xml) — DOM innerHTML 구성 → 컴포넌트 API(setValue/show)로 교체.
 * @param {Object} panelID 메시지를 표시할 컴포넌트(setValue/show 보유)
 * @param {String} msg 표시할 메시지
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.panelMsg(grp_msg, "처리되었습니다.");
 */
scwin.panelMsg = function (panelID, msg) {
    panelID.setValue(msg);
    panelID.show("");
};

// -----------------------------------------------------------------------------
// 4. 기간/일자 UI (origin: stf.xml)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name setFromToDate
 * @description 기간구분(pTp: 1주일/1·3·6개월/1·2년)에 따라 From/To 일자 컴포넌트를 자동 설정한다.
 * To 값이 비어있으면 서버 현재일 기준으로 계산한다.
 * (AS-IS: fn_setFromToDate, origin: stf.xml)
 * AS-IS 의 $c.ut.cGet* 날짜연산 → $c.date.addDate/addMonth/addYear, 값 get/set → 컴포넌트 getValue/setValue 로 교체.
 * @param {Number} pTp 기간구분 (1:1주일,2:1개월,3:3개월,4:6개월,5:1년,6:2년)
 * @param {Object} pObjFrom From 일자 컴포넌트
 * @param {Object} pObjTo To 일자 컴포넌트
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.setFromToDate(1, ibx_fromDd, ibx_toDd);
 */
scwin.setFromToDate = function (pTp, pObjFrom, pObjTo) {
    var vFrom = "";
    var vTo = pObjTo.getValue();
    if ($c.util.isEmpty(vTo)) {
        // 값이 없으면 서버 현재일 기준으로 계산 (yyyymmdd)
        vTo = $c.date.getServerDateTime().substring(0, 8);
    }
    if (pTp == 1) {
        vFrom = $c.date.addDate(vTo, -7);       // 1주일 전
    } else if (pTp == 2) {
        vFrom = $c.date.addMonth(vTo, -1);      // 1개월 전
    } else if (pTp == 3) {
        vFrom = $c.date.addMonth(vTo, -3);      // 3개월 전
    } else if (pTp == 4) {
        vFrom = $c.date.addMonth(vTo, -6);      // 6개월 전
    } else if (pTp == 5) {
        vFrom = $c.date.addYear(vTo, -1);       // 1년 전
    } else if (pTp == 6) {
        vFrom = $c.date.addYear(vTo, -2);       // 2년 전
    }
    pObjFrom.setValue(vFrom);
    pObjTo.setValue(vTo);
};

/**
 * @method
 * @name setButtonSetWithDate
 * @description 기준일자를 현재일과 비교하여 buttonSet 을 수정(setUpdateStatus)/조회(setErrorStatus) 상태로 셋팅한다.
 * (AS-IS: setButtonSetWithDate, origin: stf.xml)
 * AS-IS 의 $c.ut.cGetToday → $c.date.getServerDateTime, 값조회 → 컴포넌트 getValue, 숨은 전역 buttonSet → 파라미터로 교체.
 * @param {Object} obj 기준일자 컴포넌트(yyyymmdd)
 * @param {Boolean} includeCurDate 현재일 포함 여부
 * @param {Object} buttonSet 상태를 변경할 buttonSet 컴포넌트
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.setButtonSetWithDate(ibx_baseDd, true, buttonSet);
 */
scwin.setButtonSetWithDate = function (obj, includeCurDate, buttonSet) {
    var vCurDate = $c.date.getServerDateTime().substring(0, 8);
    var vVal = obj.getValue();
    if ($c.util.isEmpty(vVal)) {
        buttonSet.setUpdateStatus();
        return;
    } else if (includeCurDate) {
        if (vCurDate > vVal) {
            buttonSet.setErrorStatus();
        } else {
            buttonSet.setUpdateStatus();
        }
    } else {
        if (vCurDate >= vVal) {
            buttonSet.setErrorStatus();
        } else {
            buttonSet.setUpdateStatus();
        }
    }
};

/**
 * @method
 * @name setButtonSetWithDate2
 * @description 미공시(공시여부 != 'Y')건만 수정 가능하도록 buttonSet 상태를 셋팅한다.
 * (AS-IS: setButtonSetWithDate2, origin: stf.xml)
 * @param {String} gDisclsCd 공시여부('Y'/'N')
