 */
scwin.setButtonSetWithDate2 = function (gDisclsCd, buttonSet) {
    if (gDisclsCd == "Y") {
        // 공시건은 수정 불가 (상태 변경 없음)
    } else {
        buttonSet.setUpdateStatus();
    }
};

/**
 * @method
 * @name setButtonSetWithDateBnd
 * @description 채권 미공시건만 수정 가능(공시여부만으로 판단)하도록 buttonSet 상태를 셋팅한다.
